head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnClass]<br/>Body Column 정보를 사용하여 특정 Body Column 에 CSS 클래스를 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 클래스를 설정할 Body Column 의 인덱스를 설정해야 합니다. (Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다)",
        "className(필수) 파라미터로 Body Column 에 적용할 CSS 클래스 이름을 공백으로 구분하여 설정해야 합니다.",
        "기존에 setColumnClass() 메소드로 설정한 CSS 클래스가 제거되지 않습니다.",
        "CSS 클래스는 Body Column 의 td 요소에 적용됩니다.",
        "렌더링 과정에서 웹스퀘어의 기본 클래스가 추가로 설정되며 CSS 우선순위에 따라 적용되지 않은 것처럼 보일 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 생성 (가장 먼저)
    $c.gcm.createLabel('label="Column 인덱스 1 (col2) 은 숨김 처리되어 있으며, 숨겨진 Column 도 인덱스에 포함됩니다."', '', 'label1');

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성 (기본 4행)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성 (Body Column 인덱스: col1(0) ~ col4(3))
    await $c.gcm.createBasicGridView(cList);

    // Column 인덱스 1 (col2) 숨김 처리
    target1.setColumnVisible(1, false);
}



scwin.btn_setColumnClass_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let className = par_className.getText();

    // Column 인덱스로 Body Column 에 CSS 클래스 설정
    target1.setColumnClass(columnInfo, className);
    wf_body_bottom.getObj("scwin").setReturnValue("setColumnClass(" + columnInfo + ", " + className + ")");

    // getColumnClass 로 누적 설정값 확인 (기존 클래스가 제거되지 않고 누적됨)
    let rtn = target1.getColumnClass(columnInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getColumnClass(" + columnInfo + ") : " + rtn);

    // Body Column 의 데이터 행 td 요소에 적용된 className 확인 (기본 클래스 공존)
    //  - getRowCount() 만큼만 출력 (데이터 행 외 viewport 를 채우는 빈 행은 제외)
    let tdList = document.querySelectorAll("td[id*='target1_cell_'][id$='_" + columnInfo + "']");
    for (let i = 0; i < target1.getRowCount(); i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("Row " + i + " td className : " + tdList[i].className);
    }
}
